-- ═══ recurring-schedules.sql ═══════════════════════════════════════════════

-- SwiftRecurepay schedules + autonomous Autopay occurrences.
-- Idempotent: safe to re-run on existing databases.

create table if not exists public.recurring_schedules (
  id uuid primary key default gen_random_uuid(),
  owner_wallet text not null,
  beneficiary_wallet text not null,
  beneficiary_username text,
  beneficiary_label text,
  token_symbol text not null,
  amount text not null,
  amount_units text not null,
  narration text,
  frequency text not null,
  interval_days integer,
  timezone text not null default 'UTC',
  next_run_at timestamptz not null,
  last_run_at timestamptz,
  starts_at timestamptz not null default now(),
  ends_at timestamptz,
  status text not null default 'active',
  wallet_mode text not null,
  autopay_enabled boolean not null default false,
  max_runs integer,
  run_count integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.recurring_executions (
  id uuid primary key default gen_random_uuid(),
  schedule_id uuid not null references public.recurring_schedules(id) on delete cascade,
  owner_wallet text not null,
  due_at timestamptz not null,
  status text not null default 'awaiting_wallet',
  tx_hash text,
  error_message text,
  idempotency_key text not null unique,
  attempted_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz not null default now()
);

-- ─── Autonomous Autopay columns (additive) ───────────────────────────────────

alter table public.recurring_schedules
  add column if not exists autopay_enabled boolean not null default false;

alter table public.recurring_schedules
  add column if not exists authorization_status text not null default 'UNAUTHORIZED';

alter table public.recurring_schedules
  add column if not exists authorization_tx_hash text;

alter table public.recurring_schedules
  add column if not exists authorized_at timestamptz;

alter table public.recurring_schedules
  add column if not exists authorization_expires_at timestamptz;

alter table public.recurring_schedules
  add column if not exists authorized_recipient text;

alter table public.recurring_schedules
  add column if not exists authorized_token text;

alter table public.recurring_schedules
  add column if not exists max_payment_amount text;

alter table public.recurring_schedules
  add column if not exists max_payment_amount_units text;

alter table public.recurring_schedules
  add column if not exists total_limit text;

alter table public.recurring_schedules
  add column if not exists total_limit_units text;

alter table public.recurring_schedules
  add column if not exists executed_amount_units text not null default '0';

alter table public.recurring_schedules
  add column if not exists last_execution_id uuid;

alter table public.recurring_schedules
  add column if not exists last_executed_at timestamptz;

alter table public.recurring_schedules
  add column if not exists failure_count integer not null default 0;

alter table public.recurring_schedules
  add column if not exists max_retries integer not null default 4;

alter table public.recurring_schedules
  add column if not exists next_occurrence_number integer not null default 1;

alter table public.recurring_executions
  add column if not exists occurrence_number integer;

alter table public.recurring_executions
  add column if not exists amount text;

alter table public.recurring_executions
  add column if not exists amount_units text;

alter table public.recurring_executions
  add column if not exists execution_mode text not null default 'manual';

alter table public.recurring_executions
  add column if not exists provider_transaction_id text;

alter table public.recurring_executions
  add column if not exists attempt_count integer not null default 0;

alter table public.recurring_executions
  add column if not exists next_retry_at timestamptz;

alter table public.recurring_executions
  add column if not exists submitted_at timestamptz;

alter table public.recurring_executions
  add column if not exists confirmed_at timestamptz;

alter table public.recurring_executions
  add column if not exists updated_at timestamptz not null default now();

alter table public.recurring_executions
  add column if not exists lock_token text;

alter table public.recurring_executions
  add column if not exists lock_expires_at timestamptz;

-- Existing autopay_enabled rows are NOT treated as authorized.
update public.recurring_schedules
set authorization_status = 'REAUTHORIZATION_REQUIRED',
    updated_at = now()
where autopay_enabled = true
  and authorization_status in ('UNAUTHORIZED', 'REAUTHORIZATION_REQUIRED')
  and authorization_tx_hash is null
  and authorized_at is null;

-- Backfill occurrence numbers for legacy rows (stable by created_at).
with numbered as (
  select
    id,
    row_number() over (partition by schedule_id order by created_at asc) as n
  from public.recurring_executions
  where occurrence_number is null
)
update public.recurring_executions e
set occurrence_number = numbered.n
from numbered
where e.id = numbered.id;

create unique index if not exists recurring_executions_occurrence_uidx
  on public.recurring_executions (schedule_id, occurrence_number)
  where occurrence_number is not null;

create unique index if not exists recurring_executions_idempotency_uidx
  on public.recurring_executions (idempotency_key);

create index if not exists recurring_schedules_owner_wallet_idx
  on public.recurring_schedules (owner_wallet);

create index if not exists recurring_schedules_due_idx
  on public.recurring_schedules (status, next_run_at);

create index if not exists recurring_schedules_autopay_due_idx
  on public.recurring_schedules (status, autopay_enabled, authorization_status, next_run_at);

create index if not exists recurring_executions_owner_wallet_idx
  on public.recurring_executions (owner_wallet, created_at desc);

create index if not exists recurring_executions_schedule_idx
  on public.recurring_executions (schedule_id, due_at desc);

create index if not exists recurring_executions_worker_idx
  on public.recurring_executions (status, next_retry_at, created_at);

create table if not exists public.recurring_locks (
  lock_key text primary key,
  owner_token text not null,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);

create index if not exists recurring_locks_expires_idx
  on public.recurring_locks (expires_at);

alter table public.recurring_schedules enable row level security;
alter table public.recurring_executions enable row level security;
alter table public.recurring_locks enable row level security;

grant usage on schema public to service_role;
grant select, insert, update, delete on public.recurring_schedules to service_role;
grant select, insert, update, delete on public.recurring_executions to service_role;
grant select, insert, update, delete on public.recurring_locks to service_role;

-- ═══ recurring-autopay-mandates.sql ════════════════════════════════════════

-- Autopay mandates (RecurePayExecutor v2).
-- Each authorized schedule is now paid under an on-chain mandate the payer
-- created, which fixes the recipient, token and cap per period. The server
-- stores its id and passes only that id to the executor.
alter table public.recurring_schedules
  add column if not exists authorization_mandate_id text;

-- Schedules authorized under the old executor have no mandate and can't be
-- paid by the new one; ask their owners to authorize again.
update public.recurring_schedules
   set authorization_status = 'REAUTHORIZATION_REQUIRED',
       autopay_enabled = false,
       updated_at = now()
 where authorization_status = 'AUTHORIZED'
   and authorization_mandate_id is null;

-- ═══ payment-policies.sql ══════════════════════════════════════════════════

-- SwiftPay Policy Engine — per-wallet spend policy.
-- Evaluated for every PaymentIntent before it reaches the router.
-- Idempotent: safe to re-run on existing databases.

create table if not exists public.payment_policies (
  owner_wallet text primary key,
  -- bigint stored as text to avoid JS precision loss on 6-decimal units.
  per_tx_limit_units text not null default '25000000',
  daily_limit_units text not null default '100000000',
  approved_recipients jsonb not null default '[]'::jsonb,
  approved_assets jsonb not null default '["USDC"]'::jsonb,
  requires_approval_above_units text not null default '10000000',
  status text not null default 'active',
  -- IANA zone; the daily limit resets at the owner's local midnight.
  timezone text not null default 'UTC',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint payment_policies_status_check
    check (status in ('active', 'paused', 'revoked'))
);

alter table public.payment_policies
  add column if not exists timezone text not null default 'UTC';

create index if not exists payment_policies_status_idx
  on public.payment_policies (status);

-- ─── updated_at trigger ──────────────────────────────────────────────────────

create or replace function public.payment_policies_touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists payment_policies_touch_updated_at on public.payment_policies;
create trigger payment_policies_touch_updated_at
  before update on public.payment_policies
  for each row execute function public.payment_policies_touch_updated_at();

-- ─── Access ──────────────────────────────────────────────────────────────────
-- RLS on with no permissive policies: the policy row is only reachable through
-- the server-side service-role client, after the route authorizes the owner.

alter table public.payment_policies enable row level security;

grant usage on schema public to service_role;
grant select, insert, update, delete on public.payment_policies to service_role;

-- ═══ payment-policies-timezone.sql ═════════════════════════════════════════

-- The owner's IANA time zone (e.g. 'Africa/Lagos'), so the daily spending
-- limit and "spent today" reset at the owner's local midnight rather than on
-- a rolling 24-hour window. Reported by the browser; 'UTC' until then.
--
-- Safe to re-run.

alter table public.payment_policies
  add column if not exists timezone text not null default 'UTC';

-- Verify: every policy now has a time zone.
select timezone, count(*) as policies
from public.payment_policies
group by timezone;

-- ═══ payment-intents.sql ═══════════════════════════════════════════════════

-- SwiftPay Unified Payment Engine — intent ledger.
-- Every initiator (human, business, ALLIE) writes the same PaymentIntent row.
-- The chain transaction is not the source of truth; this ledger is.
-- Idempotent: safe to re-run on existing databases.

create table if not exists public.payment_intents (
  intent_id uuid primary key default gen_random_uuid(),
  initiator_type text not null,
  initiator_id text not null,
  recipient text not null,
  resolved_recipient text,
  asset text not null default 'USDC',
  -- bigint stored as text to avoid JS precision loss on 6-decimal units.
  amount_units text not null,
  chain_id integer not null,
  rail text,
  metadata jsonb,
  idempotency_key text unique,
  status text not null default 'pending',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  completed_at timestamptz,
  constraint payment_intents_initiator_type_check
    check (initiator_type in ('human', 'business', 'agent')),
  constraint payment_intents_asset_check
    check (asset in ('USDC', 'EURC')),
  constraint payment_intents_status_check
    check (status in (
      'pending', 'policy_check', 'approved', 'rejected', 'executing',
      'submitted', 'confirming', 'completed', 'failed', 'cancelled'
    ))
);

create table if not exists public.payment_attempts (
  attempt_id uuid primary key default gen_random_uuid(),
  intent_id uuid not null references public.payment_intents(intent_id) on delete cascade,
  rail text,
  executor text,
  status text not null default 'queued',
  tx_hash text,
  provider_transaction_id text,
  error_message text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint payment_attempts_status_check
    check (status in ('queued', 'submitted', 'confirmed', 'failed'))
);

create table if not exists public.payment_settlements (
  settlement_id uuid primary key default gen_random_uuid(),
  intent_id uuid not null references public.payment_intents(intent_id) on delete cascade,
  attempt_id uuid references public.payment_attempts(attempt_id) on delete set null,
  tx_hash text,
  chain_id integer,
  amount_units text not null,
  fee_units text not null default '0',
  settled_at timestamptz not null default now()
);

create index if not exists payment_intents_initiator_idx
  on public.payment_intents (initiator_id, created_at desc);

create unique index if not exists payment_intents_idempotency_uidx
  on public.payment_intents (idempotency_key)
  where idempotency_key is not null;

create index if not exists payment_intents_status_idx
  on public.payment_intents (status, created_at desc);

create index if not exists payment_attempts_intent_idx
  on public.payment_attempts (intent_id, created_at asc);

create index if not exists payment_settlements_intent_idx
  on public.payment_settlements (intent_id, settled_at asc);

-- ─── updated_at trigger ──────────────────────────────────────────────────────

create or replace function public.payment_engine_touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists payment_intents_touch_updated_at on public.payment_intents;
create trigger payment_intents_touch_updated_at
  before update on public.payment_intents
  for each row execute function public.payment_engine_touch_updated_at();

drop trigger if exists payment_attempts_touch_updated_at on public.payment_attempts;
create trigger payment_attempts_touch_updated_at
  before update on public.payment_attempts
  for each row execute function public.payment_engine_touch_updated_at();

-- ─── Access ──────────────────────────────────────────────────────────────────
-- RLS on with no permissive policies: anon/authenticated are denied outright.
-- All reads and writes go through the server-side service-role admin client,
-- which bypasses RLS after the API route has authorized the caller's wallet.

alter table public.payment_intents enable row level security;
alter table public.payment_attempts enable row level security;
alter table public.payment_settlements enable row level security;

grant usage on schema public to service_role;
grant select, insert, update, delete on public.payment_intents to service_role;
grant select, insert, update, delete on public.payment_attempts to service_role;
grant select, insert, update, delete on public.payment_settlements to service_role;

-- ═══ payment-intents-cancelled.sql ═════════════════════════════════════════

-- Adds 'cancelled' to payment_intents.status.
--
-- Cancelling used to be a UI-only act: pressing Cancel dismissed the card but
-- left the intent sitting at 'approved' in the ledger, still executable by
-- anyone who replayed its id. This gives the refusal somewhere to live, so the
-- execute route's "only an approved intent may run" check turns it down.
--
-- Safe to re-run. Existing rows are untouched — the new value only widens what
-- the constraint accepts.

alter table public.payment_intents
  drop constraint if exists payment_intents_status_check;

alter table public.payment_intents
  add constraint payment_intents_status_check
  check (status in (
    'pending', 'policy_check', 'approved', 'rejected', 'executing',
    'submitted', 'confirming', 'completed', 'failed', 'cancelled'
  ));

-- ═══ business-workspaces.sql ═══════════════════════════════════════════════

-- SwiftPay Business: workspaces, profiles, teams, invitations, payments.
-- Additive. Service role only. Run in Supabase SQL editor after profiles.sql.
-- Account model: one SwiftPay identity → Individual workspace + Business workspaces.

create table if not exists public.workspaces (
  id uuid primary key default gen_random_uuid(),
  kind text not null,
  owner_user_wallet text not null,
  name text not null,
  username text,
  status text not null default 'active',
  payment_wallet text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint workspaces_kind_check check (kind in ('individual', 'business')),
  constraint workspaces_status_check check (status in ('active', 'archived')),
  constraint workspaces_name_len check (char_length(name) between 1 and 80),
  constraint workspaces_username_format check (
    username is null
    or username ~ '^[a-z][a-z0-9_-]{2,29}$'
  )
);

create unique index if not exists workspaces_one_individual_uidx
  on public.workspaces (owner_user_wallet)
  where kind = 'individual' and status = 'active';

create unique index if not exists workspaces_username_lower_uidx
  on public.workspaces (lower(username))
  where username is not null;

create index if not exists workspaces_owner_idx
  on public.workspaces (owner_user_wallet, status, created_at desc);

alter table public.workspaces
  add column if not exists circle_wallet_id text;

create table if not exists public.workspace_members (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete restrict,
  user_wallet text not null,
  role text not null default 'member',
  status text not null default 'active',
  joined_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint workspace_members_role_check check (
    role in ('owner', 'admin', 'finance', 'member', 'viewer')
  ),
  constraint workspace_members_status_check check (
    status in ('active', 'invited', 'removed', 'left')
  ),
  constraint workspace_members_unique unique (workspace_id, user_wallet)
);

alter table public.workspace_members
  drop constraint if exists workspace_members_role_check;

alter table public.workspace_members
  add constraint workspace_members_role_check check (
    role in ('owner', 'admin', 'finance', 'member', 'viewer')
  );

create index if not exists workspace_members_wallet_idx
  on public.workspace_members (user_wallet, status);

create table if not exists public.business_profiles (
  workspace_id uuid primary key references public.workspaces(id) on delete restrict,
  description text,
  logo_url text,
  website text,
  category text,
  country text,
  contact_email text,
  contact_phone text,
  address_line text,
  social_links jsonb not null default '{}'::jsonb,
  verification_status text not null default 'UNVERIFIED',
  legal_name text,
  registration_number text,
  tax_identifier text,
  business_type text,
  industry text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint business_profiles_description_len check (
    description is null or char_length(description) <= 280
  ),
  constraint business_profiles_verification_check check (
    verification_status in (
      'UNVERIFIED',
      'PENDING',
      'VERIFIED',
      'REQUIRES_ACTION',
      'REJECTED',
      'SUSPENDED'
    )
  )
);

alter table public.business_profiles
  add column if not exists legal_name text;
alter table public.business_profiles
  add column if not exists registration_number text;
alter table public.business_profiles
  add column if not exists tax_identifier text;
alter table public.business_profiles
  add column if not exists business_type text;
alter table public.business_profiles
  add column if not exists industry text;

create table if not exists public.workspace_settings (
  workspace_id uuid primary key references public.workspaces(id) on delete restrict,
  max_members integer not null default 100,
  approval_required boolean not null default true,
  approval_threshold_units text not null default '0',
  required_approvals integer not null default 1,
  approval_policy jsonb not null default '[
    {"up_to": "1000", "required_approvals": 0},
    {"up_to": "10000", "required_approvals": 1},
    {"up_to": null, "required_approvals": 2}
  ]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint workspace_settings_max_members_check check (
    max_members between 1 and 500
  ),
  constraint workspace_settings_approvals_check check (
    required_approvals between 1 and 10
  )
);

alter table public.workspace_settings
  add column if not exists approval_policy jsonb not null default '[
    {"up_to": "1000", "required_approvals": 0},
    {"up_to": null, "required_approvals": 1}
  ]'::jsonb;

create table if not exists public.workspace_invitations (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete restrict,
  invited_user_wallet text,
  invited_username text,
  role text not null default 'member',
  status text not null default 'pending',
  invited_by_wallet text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  expires_at timestamptz not null default (now() + interval '14 days'),
  constraint workspace_invitations_role_check check (
    role in ('admin', 'finance', 'member', 'viewer')
  ),
  constraint workspace_invitations_status_check check (
    status in ('pending', 'accepted', 'declined', 'expired', 'cancelled')
  )
);

alter table public.workspace_invitations
  drop constraint if exists workspace_invitations_role_check;

alter table public.workspace_invitations
  add constraint workspace_invitations_role_check check (
    role in ('admin', 'finance', 'member', 'viewer')
  );

create index if not exists workspace_invitations_wallet_idx
  on public.workspace_invitations (invited_user_wallet, status);

create index if not exists workspace_invitations_username_idx
  on public.workspace_invitations (lower(invited_username), status);

-- Global human-readable payment identity. Never expose wallet IDs in the UI.
create table if not exists public.payment_identities (
  username text primary key,
  kind text not null,
  workspace_id uuid references public.workspaces(id) on delete restrict,
  profile_wallet text,
  destination_wallet text not null,
  display_name text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint payment_identities_kind_check check (kind in ('individual', 'business')),
  constraint payment_identities_username_format check (
    username ~ '^[a-z][a-z0-9_-]{2,29}$'
  )
);

create index if not exists payment_identities_wallet_idx
  on public.payment_identities (destination_wallet);

create index if not exists payment_identities_workspace_idx
  on public.payment_identities (workspace_id);

create table if not exists public.business_payments (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete restrict,
  direction text not null,
  asset text not null,
  amount_units text not null,
  amount_display text not null,
  counterparty_name text,
  counterparty_username text,
  counterparty_wallet text,
  memo text,
  approval_status text not null default 'DRAFT',
  transaction_status text not null default 'DRAFT',
  network text not null default 'arc',
  tx_hash text,
  circle_transaction_id text,
  idempotency_key text,
  created_by_wallet text not null,
  submitted_at timestamptz,
  completed_at timestamptz,
  failed_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint business_payments_direction_check check (
    direction in ('incoming', 'outgoing')
  ),
  constraint business_payments_asset_check check (asset in ('USDC', 'EURC')),
  constraint business_payments_approval_check check (
    approval_status in (
      'DRAFT',
      'PENDING_APPROVAL',
      'PARTIALLY_APPROVED',
      'APPROVED',
      'REJECTED',
      'NOT_REQUIRED'
    )
  ),
  constraint business_payments_tx_check check (
    transaction_status in (
      'DRAFT',
      'AUTHORIZATION_REQUIRED',
      'SUBMITTED',
      'PROCESSING',
      'COMPLETED',
      'FAILED',
      'CANCELLED'
    )
  )
);

create unique index if not exists business_payments_idempotency_uidx
  on public.business_payments (workspace_id, idempotency_key)
  where idempotency_key is not null;

create index if not exists business_payments_workspace_idx
  on public.business_payments (workspace_id, created_at desc);

create table if not exists public.payment_approvals (
  id uuid primary key default gen_random_uuid(),
  payment_id uuid not null references public.business_payments(id) on delete restrict,
  approver_wallet text not null,
  decision text not null,
  comment text,
  created_at timestamptz not null default now(),
  constraint payment_approvals_decision_check check (
    decision in ('approved', 'rejected')
  ),
  constraint payment_approvals_unique unique (payment_id, approver_wallet)
);

create index if not exists payment_approvals_payment_idx
  on public.payment_approvals (payment_id, created_at);

create table if not exists public.business_payment_requests (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete restrict,
  asset text not null default 'USDC',
  amount_display text,
  amount_units text,
  memo text,
  status text not null default 'open',
  created_by_wallet text not null,
  paid_payment_id uuid references public.business_payments(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint business_payment_requests_asset_check check (asset in ('USDC', 'EURC')),
  constraint business_payment_requests_status_check check (
    status in ('open', 'paid', 'cancelled', 'expired')
  )
);

create index if not exists business_payment_requests_workspace_idx
  on public.business_payment_requests (workspace_id, created_at desc);

