  payment_terms text,
  payment_link text,
  paid_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint business_invoices_status_check check (
    status in (
      'DRAFT',
      'SENT',
      'VIEWED',
      'PENDING',
      'PAID',
      'OVERDUE',
      'CANCELLED'
    )
  ),
