create index if not exists business_invoices_wallet_status_idx
  on public.business_invoices (wallet_address, status);

create table if not exists public.business_invoice_items (
  id uuid primary key default gen_random_uuid(),
  invoice_id uuid not null references public.business_invoices(id) on delete cascade,
  description text not null,
  quantity text not null default '1',
  unit_price text not null default '0',
  tax text not null default '0',
  total text not null default '0',
  created_at timestamptz not null default now()
);

create index if not exists business_invoice_items_invoice_idx
  on public.business_invoice_items (invoice_id);

create table if not exists public.business_invoice_payments (
  id uuid primary key default gen_random_uuid(),
  invoice_id uuid not null references public.business_invoices(id) on delete restrict,
  tx_hash text not null,
  amount text not null,
  asset text not null,
  status text not null default 'CONFIRMED',
  paid_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  constraint business_invoice_payments_tx_unique unique (tx_hash),
  constraint business_invoice_payments_asset_check check (
    asset in ('USDC', 'EURC')
  )
);

create index if not exists business_invoice_payments_invoice_idx
  on public.business_invoice_payments (invoice_id);

alter table public.account_type_history enable row level security;
alter table public.business_account_profiles enable row level security;
alter table public.business_invoices enable row level security;
alter table public.business_invoice_items enable row level security;
alter table public.business_invoice_payments enable row level security;

grant select, insert, update on public.account_type_history to service_role;
grant select, insert, update on public.business_account_profiles to service_role;
grant select, insert, update, delete on public.business_invoices to service_role;
grant select, insert, update, delete on public.business_invoice_items to service_role;
grant select, insert, update on public.business_invoice_payments to service_role;

-- Retire workspace-era business identities so Personal accounts stay clean.
-- Run this in the Supabase SQL editor before using the new Personal/Business account model.
update public.profiles
set default_workspace_id = null
where default_workspace_id in (
  select id from public.workspaces where kind = 'business'
);

delete from public.payment_identities
where kind = 'business';

update public.workspaces
set status = 'archived', updated_at = now()
where kind = 'business' and status = 'active';

delete from public.workspace_invitations
where workspace_id in (select id from public.workspaces where kind = 'business');

alter table public.business_invoices
  add column if not exists customer_username text;

alter table public.business_invoices
  add column if not exists allow_partial_payment boolean not null default false;

alter table public.business_invoices
  add column if not exists amount_received text not null default '0';

alter table public.business_invoices
  add column if not exists overpayment text not null default '0';

alter table public.business_invoices
  drop constraint if exists business_invoices_status_check;

alter table public.business_invoices
  add constraint business_invoices_status_check check (
    status in (
      'DRAFT',
      'SENT',
      'VIEWED',
      'PENDING',
      'PARTIALLY_PAID',
      'PAID',
      'OVERDUE',
      'CANCELLED'
    )
  );

alter table public.business_invoice_items
  add column if not exists discount text not null default '0';

-- ═══ business-profile-details.sql ══════════════════════════════════════════

-- Business profiles: year founded and annual volume.
--
-- Optional details set in Settings → Profile, alongside the employee band
-- (stored in the existing business_size column). None of them is required
-- for verification.
--
-- Run in the Supabase SQL editor. Safe to run more than once.

alter table public.business_account_profiles
  add column if not exists year_founded integer,
  add column if not exists annual_volume text;

alter table public.business_account_profiles
  drop constraint if exists business_account_profiles_year_founded_check;
alter table public.business_account_profiles
  add constraint business_account_profiles_year_founded_check check (
    year_founded is null or year_founded between 1800 and 2100
  );

-- ═══ business-verification-reviews.sql ═════════════════════════════════════

-- Business verification reviews.
--
-- A business with a complete profile submits a registration number or tax
-- ID. SwiftPay checks it against a free official register where one exists
-- (EU VIES, France, UK Companies House, Norway, Australia ABR, GLEIF LEI) and
-- otherwise queues it for a reviewer at /admin/business-verifications.
-- A business is shown as verified only once a review is APPROVED.
--
-- Run in the Supabase SQL editor. Safe to run more than once.

alter table public.business_account_profiles
  add column if not exists review_status text not null default 'NONE';

alter table public.business_account_profiles
  drop constraint if exists business_account_profiles_review_status_check;
alter table public.business_account_profiles
  add constraint business_account_profiles_review_status_check check (
    review_status in ('NONE', 'PENDING', 'APPROVED', 'REJECTED')
  );

create table if not exists public.business_verification_submissions (
  id uuid primary key default gen_random_uuid(),
  wallet_address text not null,
  -- Snapshot of what was checked, so a later profile edit can't rewrite it.
  business_name text not null,
  country_code text not null,
  id_type text not null,
  id_number text not null,
  status text not null default 'PENDING',
  method text not null default 'AUTOMATIC',
  -- Which register answered ("EU VIES", "GLEIF"...), and what it said.
  source text,
  registry_name text,
  registry_status text,
  -- Why it was routed to a person, or why it was rejected.
  note text,
  reason text,
  reviewed_by text,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint business_verification_status_check check (
    status in ('PENDING', 'APPROVED', 'REJECTED')
  ),
  constraint business_verification_method_check check (
    method in ('AUTOMATIC', 'MANUAL')
  ),
  constraint business_verification_type_check check (
    id_type in ('VAT', 'REGISTRATION', 'TAX', 'LEI')
  )
);

create index if not exists business_verification_wallet_idx
  on public.business_verification_submissions (wallet_address, created_at desc);

create index if not exists business_verification_pending_idx
  on public.business_verification_submissions (created_at)
  where status = 'PENDING';

-- One registration can verify one business: a second business presenting an
-- already-approved number can't be approved with it.
create unique index if not exists business_verification_approved_unique
  on public.business_verification_submissions (country_code, id_type, id_number)
  where status = 'APPROVED';

-- Server-only table: the service role reads and writes it; no public access.
alter table public.business_verification_submissions enable row level security;

-- The server reads and writes this table with the service role; without the
-- grant every request fails with "permission denied" (42501).
grant all privileges on table public.business_verification_submissions to postgres, service_role;

-- ═══ business-payroll.sql ══════════════════════════════════════════════════

-- SwiftPay Payroll: Business-exclusive financial payroll infrastructure
-- Additive. Run in Supabase SQL editor.
-- Scope: account_id represents the Business account wallet address.

create table if not exists public.payroll_team_members (
  id uuid primary key default gen_random_uuid(),
  account_id text not null,
  member_type text not null default 'EMPLOYEE',
  full_name text not null,
  email text,
  role text,
  payment_destination_type text not null default 'SWIFTPAY_USER',
  swiftpay_username text,
  wallet_address text not null,
  preferred_asset text not null default 'USDC',
  default_payment_amount text not null default '0',
  payment_frequency text not null default 'MONTHLY',
  status text not null default 'ACTIVE',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  archived_at timestamptz,
  constraint payroll_team_members_type_check check (member_type in ('EMPLOYEE', 'CONTRACTOR')),
  constraint payroll_team_members_destination_check check (payment_destination_type in ('SWIFTPAY_USER', 'EXTERNAL_WALLET')),
  constraint payroll_team_members_frequency_check check (payment_frequency in ('WEEKLY', 'BIWEEKLY', 'MONTHLY', 'MANUAL')),
  constraint payroll_team_members_status_check check (status in ('ACTIVE', 'PAUSED', 'ARCHIVED'))
);

create index if not exists payroll_team_members_account_idx
  on public.payroll_team_members (account_id, status, created_at desc);

create table if not exists public.payroll_groups (
  id uuid primary key default gen_random_uuid(),
  account_id text not null,
  name text not null,
  description text,
  default_schedule text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists payroll_groups_account_idx
  on public.payroll_groups (account_id, created_at desc);

create table if not exists public.payroll_group_members (
  id uuid primary key default gen_random_uuid(),
  payroll_group_id uuid not null references public.payroll_groups(id) on delete cascade,
  team_member_id uuid not null references public.payroll_team_members(id) on delete cascade,
  created_at timestamptz not null default now(),
  constraint payroll_group_members_unique unique (payroll_group_id, team_member_id)
);

create table if not exists public.payroll_schedules (
  id uuid primary key default gen_random_uuid(),
  account_id text not null,
  payroll_group_id uuid references public.payroll_groups(id) on delete set null,
  frequency text not null default 'MONTHLY',
  schedule_config jsonb not null default '{}'::jsonb,
  next_run_at timestamptz,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint payroll_schedules_frequency_check check (frequency in ('WEEKLY', 'BIWEEKLY', 'MONTHLY', 'MANUAL'))
);

create index if not exists payroll_schedules_account_idx
  on public.payroll_schedules (account_id, is_active);

create table if not exists public.payroll_runs (
  id uuid primary key default gen_random_uuid(),
  account_id text not null,
  payroll_group_id uuid references public.payroll_groups(id) on delete set null,
  payroll_schedule_id uuid references public.payroll_schedules(id) on delete set null,
  name text not null,
  source text not null default 'MANUAL',
  status text not null default 'DRAFT',
  asset text not null default 'USDC',
  total_amount text not null default '0',
  total_fees text not null default '0',
  total_required text not null default '0',
  recipient_count integer not null default 0,
  approved_by text,
  approved_at timestamptz,
  approval_metadata jsonb default '{}'::jsonb,
  snapshot jsonb,
  execution_started_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint payroll_runs_source_check check (source in ('MANUAL', 'SCHEDULED')),
  constraint payroll_runs_status_check check (
    status in ('DRAFT', 'READY', 'APPROVED', 'PROCESSING', 'COMPLETED', 'PARTIALLY_COMPLETED', 'FAILED', 'CANCELLED')
  )
);

create index if not exists payroll_runs_account_idx
  on public.payroll_runs (account_id, status, created_at desc);

create table if not exists public.payroll_items (
  id uuid primary key default gen_random_uuid(),
  payroll_run_id uuid not null references public.payroll_runs(id) on delete cascade,
  team_member_id uuid references public.payroll_team_members(id) on delete set null,
  recipient_name_snapshot text not null,
  recipient_destination_snapshot text not null,
  recipient_username_snapshot text,
  base_amount text not null default '0',
  adjustment_amount text not null default '0',
  total_amount text not null default '0',
  asset text not null default 'USDC',
  status text not null default 'PENDING',
  failure_reason text,
  attempt_count integer not null default 0,
  transaction_id text,
  blockchain_tx_hash text,
  settled_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint payroll_items_status_check check (
    status in ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'RETRYING')
  )
);

create index if not exists payroll_items_run_idx
  on public.payroll_items (payroll_run_id, status);

create table if not exists public.payroll_adjustments (
  id uuid primary key default gen_random_uuid(),
  payroll_item_id uuid not null references public.payroll_items(id) on delete cascade,
  type text not null,
  amount text not null,
  reason text,
  created_at timestamptz not null default now(),
  constraint payroll_adjustments_type_check check (type in ('BONUS', 'DEDUCTION', 'MANUAL_ADJUSTMENT'))
);

create table if not exists public.payroll_executions (
  id uuid primary key default gen_random_uuid(),
  payroll_run_id uuid not null references public.payroll_runs(id) on delete cascade,
  payroll_item_id uuid references public.payroll_items(id) on delete set null,
  batch_payment_id text,
  transaction_id text,
  blockchain_transaction_hash text,
  idempotency_key text not null unique,
  status text not null,
  attempt_number integer not null default 1,
  failure_reason text,
  started_at timestamptz not null default now(),
  completed_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists payroll_executions_run_idx
  on public.payroll_executions (payroll_run_id, status);

create table if not exists public.payroll_audit_logs (
  id uuid primary key default gen_random_uuid(),
  account_id text not null,
  payroll_run_id uuid references public.payroll_runs(id) on delete set null,
  action text not null,
  actor_id text not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists payroll_audit_logs_account_idx
  on public.payroll_audit_logs (account_id, created_at desc);

