-- ═══ referral-and-swiftpoints.sql ══════════════════════════════════════════

-- ============================================================================
-- SwiftPay Referral & SwiftPoints System Schema
-- Production-ready PostgreSQL Schema for Universal Referral Tiers & SwiftPoints Ledger
-- ============================================================================

-- 1. Referral Profiles
create table if not exists public.referral_profiles (
  id uuid primary key default gen_random_uuid(),
  wallet_address text not null unique references public.profiles(wallet_address) on delete restrict,
  referral_token text not null unique,
  total_successful_referrals integer not null default 0 check (total_successful_referrals >= 0),
  successful_personal_referrals integer not null default 0 check (successful_personal_referrals >= 0),
  successful_business_referrals integer not null default 0 check (successful_business_referrals >= 0),
  current_tier text not null default 'STARTER' check (current_tier in ('STARTER', 'BUILDER', 'ARCHITECT', 'AMBASSADOR')),
  tier_upgraded_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists referral_profiles_wallet_idx on public.referral_profiles (wallet_address);
create index if not exists referral_profiles_token_idx on public.referral_profiles (referral_token);
create index if not exists referral_profiles_tier_idx on public.referral_profiles (current_tier);

-- 2. Referral Attributions (Visitor Clicks)
create table if not exists public.referral_attributions (
  id uuid primary key default gen_random_uuid(),
  referral_token text not null,
  referrer_wallet text not null references public.profiles(wallet_address) on delete cascade,
  visitor_id text,
  ip_hash text,
  user_agent text,
  referer text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists referral_attributions_token_idx on public.referral_attributions (referral_token, created_at desc);
create index if not exists referral_attributions_referrer_idx on public.referral_attributions (referrer_wallet, created_at desc);

-- 3. Referrals (Core Lifecycle State Machine)
create table if not exists public.referrals (
  id uuid primary key default gen_random_uuid(),
  referrer_wallet text not null references public.profiles(wallet_address) on delete restrict,
  referred_wallet text not null unique references public.profiles(wallet_address) on delete restrict,
  referral_token text not null,
  referred_username_snapshot text,
  referrer_username_snapshot text,
  referred_account_type text not null default 'PERSONAL' check (referred_account_type in ('PERSONAL', 'BUSINESS')),
  status text not null default 'CLICKED' check (
    status in ('CLICKED', 'SIGNED_UP', 'VERIFIED', 'ACTIVATED', 'PENDING_QUALIFICATION', 'QUALIFIED', 'REWARDED', 'FRAUD_REVIEW', 'REJECTED', 'REVERSED')
  ),
  fraud_status text not null default 'LOW_RISK' check (
    fraud_status in ('LOW_RISK', 'MEDIUM_RISK', 'HIGH_RISK', 'REVIEW_REQUIRED', 'BLOCKED')
  ),
  tier_at_qualification text check (tier_at_qualification in ('STARTER', 'BUILDER', 'ARCHITECT', 'AMBASSADOR')),
  successful_referral_position integer,
  direct_reward_amount numeric not null default 0,
  clicked_at timestamptz,
  signed_up_at timestamptz,
  verified_at timestamptz,
  activated_at timestamptz,
  qualified_at timestamptz,
  rewarded_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint referrals_no_self_referral check (lower(referrer_wallet) <> lower(referred_wallet))
);

create index if not exists referrals_referrer_idx on public.referrals (referrer_wallet, created_at desc);
create index if not exists referrals_referred_idx on public.referrals (referred_wallet);
create index if not exists referrals_status_idx on public.referrals (status);
create index if not exists referrals_token_idx on public.referrals (referral_token);

-- 4. Referral Qualifications
create table if not exists public.referral_qualifications (
  id uuid primary key default gen_random_uuid(),
  referral_id uuid not null unique references public.referrals(id) on delete cascade,
  referred_wallet text not null references public.profiles(wallet_address) on delete restrict,
  referrer_wallet text not null references public.profiles(wallet_address) on delete restrict,
  account_type text not null check (account_type in ('PERSONAL', 'BUSINESS')),
  tier_at_qualification text not null check (tier_at_qualification in ('STARTER', 'BUILDER', 'ARCHITECT', 'AMBASSADOR')),
  qualification_method text not null check (qualification_method in ('TRANSACTION_COUNT', 'TRANSACTION_VOLUME', 'BUSINESS_VOLUME')),
  qualifying_transaction_count integer not null default 0,
  qualifying_transaction_volume numeric not null default 0,
  activation_balance numeric not null default 0,
  policy_version text not null default '1.0',
  qualification_snapshot jsonb not null default '{}'::jsonb,
  referrer_reward_points numeric not null default 0,
  referred_reward_points numeric not null default 0,
  created_at timestamptz not null default now()
);

create index if not exists referral_qualifications_referrer_idx on public.referral_qualifications (referrer_wallet);
create index if not exists referral_qualifications_referred_idx on public.referral_qualifications (referred_wallet);

-- 5. Referral Tier History
create table if not exists public.referral_tier_history (
  id uuid primary key default gen_random_uuid(),
  wallet_address text not null references public.profiles(wallet_address) on delete cascade,
  previous_tier text not null check (previous_tier in ('STARTER', 'BUILDER', 'ARCHITECT', 'AMBASSADOR')),
  new_tier text not null check (new_tier in ('STARTER', 'BUILDER', 'ARCHITECT', 'AMBASSADOR')),
  total_successful_referrals integer not null,
  referral_id uuid references public.referrals(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists referral_tier_history_wallet_idx on public.referral_tier_history (wallet_address, created_at desc);

-- 6. SwiftPoints Accounts (Balance Cache Layer)
create table if not exists public.swiftpoints_accounts (
  id uuid primary key default gen_random_uuid(),
  wallet_address text not null unique references public.profiles(wallet_address) on delete restrict,
  available_balance_units bigint not null default 0 check (available_balance_units >= 0),
  pending_balance_units bigint not null default 0 check (pending_balance_units >= 0),
  lifetime_earned_units bigint not null default 0 check (lifetime_earned_units >= 0),
  lifetime_redeemed_units bigint not null default 0 check (lifetime_redeemed_units >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists swiftpoints_accounts_wallet_idx on public.swiftpoints_accounts (wallet_address);

-- 7. SwiftPoints Ledger Entries (Immutable Financial Source of Truth)
create table if not exists public.swiftpoints_ledger_entries (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.swiftpoints_accounts(id) on delete restrict,
  wallet_address text not null references public.profiles(wallet_address) on delete restrict,
  entry_type text not null check (
    entry_type in (
      'REFERRER_PERSONAL_QUALIFICATION_REWARD',
      'REFERRER_BUSINESS_QUALIFICATION_REWARD',
      'REFERRED_PERSONAL_QUALIFICATION_REWARD',
      'REFERRED_BUSINESS_QUALIFICATION_REWARD',
      'REFERRER_PERSONAL_ACTIVITY_CASHBACK',
      'REFERRER_BUSINESS_ACTIVITY_CASHBACK',
      'REDEMPTION',
      'ADMIN_ADJUSTMENT',
      'REVERSAL'
    )
  ),
  amount_units bigint not null, -- 100 units = 1 SwiftPoint
  display_amount numeric not null, -- amount_units / 100
  usdc_equivalent numeric not null, -- display_amount * 0.01
  status text not null default 'COMPLETED' check (status in ('PENDING', 'COMPLETED', 'FAILED', 'REVERSED')),
  idempotency_key text not null unique,
  referral_id uuid references public.referrals(id) on delete set null,
  transaction_id text,
  campaign_id text,
  original_ledger_entry_id uuid references public.swiftpoints_ledger_entries(id) on delete set null,
  description text not null,
  metadata jsonb not null default '{}'::jsonb,
  policy_version text not null default '1.0',
  created_at timestamptz not null default now(),
  created_by text not null default 'system'
);

create index if not exists swiftpoints_ledger_wallet_idx on public.swiftpoints_ledger_entries (wallet_address, created_at desc);
create index if not exists swiftpoints_ledger_account_idx on public.swiftpoints_ledger_entries (account_id, created_at desc);
create index if not exists swiftpoints_ledger_type_idx on public.swiftpoints_ledger_entries (entry_type);
create index if not exists swiftpoints_ledger_tx_idx on public.swiftpoints_ledger_entries (transaction_id) where transaction_id is not null;

-- 8. SwiftPoints Redemptions
create table if not exists public.swiftpoints_redemptions (
  id uuid primary key default gen_random_uuid(),
  wallet_address text not null references public.profiles(wallet_address) on delete restrict,
  points_redeemed numeric not null check (points_redeemed >= 100),
  amount_units bigint not null check (amount_units >= 10000),
  usdc_amount numeric not null check (usdc_amount >= 1.0),
  destination_wallet text not null,
  status text not null default 'PENDING' check (status in ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'REVERSED')),
  idempotency_key text not null unique,
  ledger_entry_id uuid references public.swiftpoints_ledger_entries(id) on delete set null,
  tx_hash text,
  error_message text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists swiftpoints_redemptions_wallet_idx on public.swiftpoints_redemptions (wallet_address, created_at desc);
create index if not exists swiftpoints_redemptions_status_idx on public.swiftpoints_redemptions (status);

-- 9. Referral Activity Rewards (Referrer-only Ongoing Cashback)
create table if not exists public.referral_activity_rewards (
  id uuid primary key default gen_random_uuid(),
  referral_id uuid not null references public.referrals(id) on delete cascade,
  referrer_wallet text not null references public.profiles(wallet_address) on delete restrict,
  referred_wallet text not null references public.profiles(wallet_address) on delete restrict,
  transaction_id text not null,
  transaction_amount numeric not null,
  transaction_currency text not null default 'USDC',
  account_type text not null check (account_type in ('PERSONAL', 'BUSINESS')),
  referrer_tier text not null check (referrer_tier in ('STARTER', 'BUILDER', 'ARCHITECT', 'AMBASSADOR')),
  cashback_points numeric not null,
  amount_units bigint not null,
  usdc_equivalent numeric not null,
  ledger_entry_id uuid references public.swiftpoints_ledger_entries(id) on delete set null,
  policy_version text not null default '1.0',
  created_at timestamptz not null default now(),
  constraint referral_activity_rewards_unique_tx unique (transaction_id, referrer_wallet)
);

create index if not exists referral_activity_referrer_idx on public.referral_activity_rewards (referrer_wallet, created_at desc);
create index if not exists referral_activity_referred_idx on public.referral_activity_rewards (referred_wallet);

-- 10. Referral Risk Assessments
create table if not exists public.referral_risk_assessments (
  id uuid primary key default gen_random_uuid(),
  referral_id uuid references public.referrals(id) on delete cascade,
  wallet_address text not null references public.profiles(wallet_address) on delete cascade,
  risk_level text not null default 'LOW_RISK' check (risk_level in ('LOW_RISK', 'MEDIUM_RISK', 'HIGH_RISK', 'REVIEW_REQUIRED', 'BLOCKED')),
  reasons text[] not null default '{}',
  signals jsonb not null default '{}'::jsonb,
  reviewed_by text,
  reviewed_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists referral_risk_wallet_idx on public.referral_risk_assessments (wallet_address);
create index if not exists referral_risk_level_idx on public.referral_risk_assessments (risk_level);

-- 11. Referral Audit Logs
create table if not exists public.referral_audit_logs (
  id uuid primary key default gen_random_uuid(),
  admin_id text not null,
  action text not null,
  target_type text not null,
  target_id text not null,
  reason text not null,
  changes jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists referral_audit_target_idx on public.referral_audit_logs (target_type, target_id);
create index if not exists referral_audit_created_idx on public.referral_audit_logs (created_at desc);

-- 12. Referral Progress Payments (one row per counted payment; volume = sum)
create table if not exists public.referral_progress_payments (
  id uuid primary key default gen_random_uuid(),
  referral_id uuid not null references public.referrals(id) on delete cascade,
  tx_hash text not null,
  amount_usd numeric not null check (amount_usd > 0),
  source text not null default 'activity',
  created_at timestamptz not null default now(),
  constraint referral_progress_payments_unique_tx unique (referral_id, tx_hash)
);

create index if not exists referral_progress_payments_referral_idx on public.referral_progress_payments (referral_id);

-- Security: Row Level Security & Grants
alter table public.referral_profiles enable row level security;
alter table public.referral_attributions enable row level security;
alter table public.referrals enable row level security;
alter table public.referral_qualifications enable row level security;
alter table public.referral_tier_history enable row level security;
alter table public.swiftpoints_accounts enable row level security;
alter table public.swiftpoints_ledger_entries enable row level security;
alter table public.swiftpoints_redemptions enable row level security;
alter table public.referral_activity_rewards enable row level security;
alter table public.referral_risk_assessments enable row level security;
alter table public.referral_audit_logs enable row level security;
alter table public.referral_progress_payments enable row level security;

grant usage on schema public to service_role;
grant all on all tables in schema public to service_role;

-- ═══ referral-progress-payments.sql ════════════════════════════════════════

-- Payments counted toward a referral's qualification volume.
--
-- One row per (referral, transaction). The unique key lets the live payment
-- report and the dashboard's chain sync record the same payment at the same
-- moment without counting it twice: the database keeps one row, and volume
-- is always the sum of these rows.
--
-- Safe to re-run.

create table if not exists public.referral_progress_payments (
  id uuid primary key default gen_random_uuid(),
  referral_id uuid not null references public.referrals(id) on delete cascade,
  -- On-chain hash, or the RecurePay occurrence id when no hash is known.
  tx_hash text not null,
  amount_usd numeric not null check (amount_usd > 0),
  source text not null default 'activity',
  created_at timestamptz not null default now(),
  constraint referral_progress_payments_unique_tx unique (referral_id, tx_hash)
);

create index if not exists referral_progress_payments_referral_idx
  on public.referral_progress_payments (referral_id);

alter table public.referral_progress_payments enable row level security;
grant all on public.referral_progress_payments to service_role;

-- Verify: the table exists and is empty or holds counted payments.
select count(*) as counted_payments from public.referral_progress_payments;

-- ═══ swiftpoints-economy-and-auto-deposit.sql ══════════════════════════════

-- SwiftPoints economy extensions + Earn auto-deposit.
--
-- Adds two ways points move besides referral rewards (purchase and gift), a
-- one-time entitlement unlock, and the rule table behind Earn auto-deposit.
--
-- Safe to re-run.

-- 1. Widen the ledger entry types.
--    Also adds TRANSACTION_CASHBACK, which the TypeScript union already had
--    but the constraint did not — writing one would have failed at insert.
alter table public.swiftpoints_ledger_entries
  drop constraint if exists swiftpoints_ledger_entries_entry_type_check;

alter table public.swiftpoints_ledger_entries
  add constraint swiftpoints_ledger_entries_entry_type_check check (
    entry_type in (
      'REFERRER_PERSONAL_QUALIFICATION_REWARD',
      'REFERRER_BUSINESS_QUALIFICATION_REWARD',
      'REFERRED_PERSONAL_QUALIFICATION_REWARD',
      'REFERRED_BUSINESS_QUALIFICATION_REWARD',
      'REFERRER_PERSONAL_ACTIVITY_CASHBACK',
      'REFERRER_BUSINESS_ACTIVITY_CASHBACK',
      'TRANSACTION_CASHBACK',
      'REDEMPTION',
      'PURCHASE',
      'GIFT_SENT',
      'GIFT_RECEIVED',
      'ENTITLEMENT_UNLOCK',
      'ADMIN_ADJUSTMENT',
      'REVERSAL'
    )
  );

-- 2. Entitlements: features unlocked by spending points, for 6 months at a time.
--    One row per wallet per feature: a renewal extends `expires_at` rather
--    than inserting again, so the unique constraint still makes a
--    double-click harmless.
create table if not exists public.swiftpoints_entitlements (
  id uuid primary key default gen_random_uuid(),
  wallet_address text not null references public.profiles(wallet_address) on delete cascade,
  feature text not null check (feature in ('EARN_AUTO_DEPOSIT')),
  points_spent integer not null check (points_spent >= 0),
  ledger_entry_id uuid references public.swiftpoints_ledger_entries(id) on delete set null,
  granted_at timestamptz not null default now(),
  renewed_at timestamptz,
  -- The access is active while now() < expires_at.
  expires_at timestamptz not null default (now() + interval '6 months'),
  unique (wallet_address, feature)
);

-- Existing one-time grants become a year from when they were granted.
alter table public.swiftpoints_entitlements
  add column if not exists renewed_at timestamptz;

alter table public.swiftpoints_entitlements
  add column if not exists expires_at timestamptz;

update public.swiftpoints_entitlements
  set expires_at = granted_at + interval '6 months'
  where expires_at is null;

alter table public.swiftpoints_entitlements
  alter column expires_at set default (now() + interval '6 months');

alter table public.swiftpoints_entitlements
  alter column expires_at set not null;

create index if not exists swiftpoints_entitlements_expiry_idx
  on public.swiftpoints_entitlements (feature, expires_at);

create index if not exists swiftpoints_entitlements_wallet_idx
  on public.swiftpoints_entitlements (wallet_address);

-- 3. Purchases: points bought with on-chain USDC.
--    tx_hash is unique so one payment can never be credited twice.
create table if not exists public.swiftpoints_purchases (
  id uuid primary key default gen_random_uuid(),
  wallet_address text not null references public.profiles(wallet_address) on delete restrict,
  points integer not null check (points > 0),
  usdc_amount numeric not null check (usdc_amount > 0),
  chain_id integer not null,
  tx_hash text not null unique,
  status text not null default 'COMPLETED' check (status in ('PENDING', 'COMPLETED', 'FAILED')),
  ledger_entry_id uuid references public.swiftpoints_ledger_entries(id) on delete set null,
  error_message text,
  created_at timestamptz not null default now()
);

create index if not exists swiftpoints_purchases_wallet_idx
  on public.swiftpoints_purchases (wallet_address, created_at desc);

-- 4. Gifts: points moved wallet to wallet.
--    Two ledger entries back each row (debit the sender, credit the
--    recipient); this table is the human-readable pairing of the two.
create table if not exists public.swiftpoints_gifts (
  id uuid primary key default gen_random_uuid(),
  sender_wallet text not null references public.profiles(wallet_address) on delete restrict,
  recipient_wallet text not null references public.profiles(wallet_address) on delete restrict,
  points integer not null check (points > 0),
  note text,
  sender_ledger_entry_id uuid references public.swiftpoints_ledger_entries(id) on delete set null,
  recipient_ledger_entry_id uuid references public.swiftpoints_ledger_entries(id) on delete set null,
  idempotency_key text not null unique,
  created_at timestamptz not null default now(),
  constraint swiftpoints_gifts_not_self check (sender_wallet <> recipient_wallet)
);

create index if not exists swiftpoints_gifts_sender_idx
  on public.swiftpoints_gifts (sender_wallet, created_at desc);
create index if not exists swiftpoints_gifts_recipient_idx
  on public.swiftpoints_gifts (recipient_wallet, created_at desc);

-- 5. Earn auto-deposit rules.
--    mode SWEEP     -> offered for one-tap confirmation when the owner opens
--                      the app; the owner still signs.
--    mode UNATTENDED -> executed by the operator through
--                      EarnAutoSaveExecutor against a standing allowance.
create table if not exists public.earn_auto_deposit_rules (
  id uuid primary key default gen_random_uuid(),
  wallet_address text not null unique references public.profiles(wallet_address) on delete cascade,
  mode text not null check (mode in ('SWEEP', 'UNATTENDED')),
  vault_address text not null,
  amount_usdc numeric not null check (amount_usdc > 0),
  frequency text not null check (frequency in ('daily', 'weekly', 'monthly')),
  -- Liquid USDC that must survive the deposit, so a rule can never drain the
  -- wallet below what the owner needs on hand.
  min_balance_floor numeric not null default 0 check (min_balance_floor >= 0),
  enabled boolean not null default true,
  last_run_at timestamptz,
  next_run_at timestamptz not null default now(),
  -- Set when a run fails so the UI can explain itself instead of going quiet.
  last_error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists earn_auto_deposit_rules_due_idx
  on public.earn_auto_deposit_rules (next_run_at)
  where enabled;

-- 6. Executions: one row per attempt, for history and idempotency.
create table if not exists public.earn_auto_deposit_executions (
  id uuid primary key default gen_random_uuid(),
  rule_id uuid not null references public.earn_auto_deposit_rules(id) on delete cascade,
  wallet_address text not null,
  mode text not null check (mode in ('SWEEP', 'UNATTENDED')),
  amount_usdc numeric not null,
  vault_address text not null,
  status text not null check (status in ('SUCCEEDED', 'FAILED', 'SKIPPED')),
  reason text,
  tx_hash text,
  execution_id text not null unique,
  created_at timestamptz not null default now()
);

create index if not exists earn_auto_deposit_executions_wallet_idx
  on public.earn_auto_deposit_executions (wallet_address, created_at desc);

-- ═══ swiftpoints-entitlement-term.sql ══════════════════════════════════════

-- Premium entitlements: one-time unlock -> 6-month term.
--
-- Run this if you already applied swiftpoints-economy-and-auto-deposit.sql
-- before the term change. Running the full file again does the same thing;
-- this is just the delta.
--
-- Safe to re-run.

-- 1. Add the term columns.
alter table public.swiftpoints_entitlements
  add column if not exists renewed_at timestamptz;

alter table public.swiftpoints_entitlements
  add column if not exists expires_at timestamptz;

-- 2. Existing one-time grants become a 6-month term from when they were
--    granted. Anyone who unlocked under the old model keeps access until
--    then rather than losing it the moment this lands.
update public.swiftpoints_entitlements
  set expires_at = granted_at + interval '6 months'
  where expires_at is null;

-- 3. Lock the column down now that every row has a value.
alter table public.swiftpoints_entitlements
  alter column expires_at set default (now() + interval '6 months');

alter table public.swiftpoints_entitlements
  alter column expires_at set not null;

create index if not exists swiftpoints_entitlements_expiry_idx
  on public.swiftpoints_entitlements (feature, expires_at);

-- 4. Verify: every row should show an expiry, and active should be true for
--    anything granted in the last 6 months.
select
  wallet_address,
  feature,
  granted_at,
  expires_at,
  (expires_at > now()) as active
from public.swiftpoints_entitlements
order by expires_at desc;

-- ═══ swiftpoints-payroll-feature.sql ═══════════════════════════════════════

-- Add PAYROLL_AUTO_SCHEDULE to the premium features a wallet can unlock.
--
-- The entitlements table pins `feature` with a CHECK constraint, so a new
-- premium feature needs the constraint widened before anything can be granted.
--
-- Safe to re-run.

alter table public.swiftpoints_entitlements
  drop constraint if exists swiftpoints_entitlements_feature_check;

alter table public.swiftpoints_entitlements
  add constraint swiftpoints_entitlements_feature_check check (
    feature in ('EARN_AUTO_DEPOSIT', 'PAYROLL_AUTO_SCHEDULE')
  );

-- Verify: both features are now grantable, and existing rows are untouched.
select feature, count(*) as granted
from public.swiftpoints_entitlements
group by feature;

-- ═══ swiftpoints-and-auto-deposit-rls.sql ══════════════════════════════════

-- Lock down SwiftPoints economy and Earn auto-deposit tables.
-- These were created without row level security, which lets anyone holding the
-- public anon key read and write them. The app only touches them through the
-- service-role client (lib/referral/db.ts, lib/earn/auto-deposit.ts), which
-- bypasses RLS, so a deny-all client policy is safe.

do $$
declare
  t text;
begin
  foreach t in array array[
    'swiftpoints_entitlements',
    'swiftpoints_purchases',
    'swiftpoints_gifts',
    'earn_auto_deposit_rules',
    'earn_auto_deposit_executions'
  ]
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select, insert, update, delete on public.%I to service_role', t);
    execute format('drop policy if exists %I on public.%I', t || '_no_client_access', t);
    execute format(
      'create policy %I on public.%I for all using (false) with check (false)',
      t || '_no_client_access', t
    );
  end loop;
end
$$;

-- ═══ swift-circle.sql ══════════════════════════════════════════════════════

-- SwiftCircle: collaborative financial workspace
-- Additive only. Do not alter existing SwiftPay financial tables destructively.
-- Run in Supabase SQL editor. Service role only.
-- Identity: user_wallet is the SwiftPay user id (checksum-normalized lowercase address).

-- ─── Circles ────────────────────────────────────────────────────────────────
create table if not exists public.circles (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  description text,
  image_url text,
  creator_user_wallet text not null,
  host_user_wallet text not null,
  currency text not null default 'USDC',
  visibility text not null default 'private',
  status text not null default 'active',
  financial_frozen boolean not null default false,
  version integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circles_name_len check (char_length(name) between 1 and 80),
  constraint circles_description_len check (
    description is null or char_length(description) <= 280
  ),
  constraint circles_status_check check (status in ('active', 'archived')),
  constraint circles_visibility_check check (visibility in ('private')),
  constraint circles_currency_check check (currency in ('USDC', 'EURC'))
);

create index if not exists circles_host_idx
  on public.circles (host_user_wallet, status, created_at desc);

create index if not exists circles_creator_idx
  on public.circles (creator_user_wallet, created_at desc);

-- ─── Members ────────────────────────────────────────────────────────────────
create table if not exists public.circle_members (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  user_wallet text not null,
  role text not null default 'member',
  status text not null default 'active',
  joined_at timestamptz,
  left_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circle_members_role_check check (role in ('host', 'admin', 'member')),
  constraint circle_members_status_check check (
    status in ('active', 'removed', 'left')
  ),
  constraint circle_members_unique unique (circle_id, user_wallet)
);

create index if not exists circle_members_circle_idx
  on public.circle_members (circle_id);

create index if not exists circle_members_user_idx
  on public.circle_members (user_wallet);

create index if not exists circle_members_active_idx
  on public.circle_members (circle_id, status)
  where status = 'active';

-- ─── Invitations ────────────────────────────────────────────────────────────
create table if not exists public.circle_invitations (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  inviter_user_wallet text not null,
  invitee_user_wallet text not null,
  invitee_username text,
  status text not null default 'pending',
  expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  responded_at timestamptz,
  constraint circle_invitations_status_check check (
    status in ('pending', 'accepted', 'declined', 'expired', 'cancelled')
  )
);

create index if not exists circle_invitations_invitee_idx
  on public.circle_invitations (invitee_user_wallet, status, created_at desc);

create index if not exists circle_invitations_circle_idx
  on public.circle_invitations (circle_id, status, created_at desc);

create unique index if not exists circle_invitations_pending_uidx
  on public.circle_invitations (circle_id, invitee_user_wallet)
  where status = 'pending';

-- ─── Chat ───────────────────────────────────────────────────────────────────
create table if not exists public.circle_messages (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  sender_user_wallet text,
  message_type text not null default 'text',
  content text not null default '',
  reply_to_message_id uuid references public.circle_messages(id) on delete set null,
  delivery_state text not null default 'sent',
  created_at timestamptz not null default now(),
  edited_at timestamptz,
  deleted_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  constraint circle_messages_type_check check (
    message_type in ('text', 'system', 'financial_card')
  ),
  constraint circle_messages_delivery_check check (
    delivery_state in ('sent', 'delivered')
  ),
  constraint circle_messages_content_len check (char_length(content) <= 4000)
);

create index if not exists circle_messages_circle_created_idx
  on public.circle_messages (circle_id, created_at);

create table if not exists public.circle_message_reads (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  user_wallet text not null,
  last_read_message_id uuid references public.circle_messages(id) on delete set null,
  last_read_at timestamptz not null default now(),
  constraint circle_message_reads_unique unique (circle_id, user_wallet)
);

create table if not exists public.circle_message_reports (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  message_id uuid not null references public.circle_messages(id) on delete restrict,
  reporter_user_wallet text not null,
  reason text not null,
  created_at timestamptz not null default now(),
  constraint circle_message_reports_reason_len check (char_length(reason) between 1 and 280),
  constraint circle_message_reports_unique unique (message_id, reporter_user_wallet)
);

-- ─── Payments ───────────────────────────────────────────────────────────────
create table if not exists public.circle_payment_intents (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  sender_user_wallet text not null,
  total_amount text not null,
  total_amount_units text not null,
  asset text not null default 'USDC',
  payment_mode text not null,
  note text,
  status text not null default 'proposed',
  idempotency_key text not null,
  risk_decision text not null default 'ALLOW',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circle_payment_mode_check check (
    payment_mode in ('individual', 'multiple', 'everyone', 'equal_split', 'custom_split')
  ),
  constraint circle_payment_status_check check (
    status in (
      'proposed',
      'executing',
      'submitted',
      'confirmed',
      'failed',
      'cancelled'
    )
  ),
  constraint circle_payment_asset_check check (asset in ('USDC', 'EURC'))
);

create unique index if not exists circle_payment_intents_idem_uidx
  on public.circle_payment_intents (sender_user_wallet, idempotency_key);

create index if not exists circle_payment_intents_circle_idx
  on public.circle_payment_intents (circle_id, created_at desc);

create table if not exists public.circle_payment_recipients (
  id uuid primary key default gen_random_uuid(),
  payment_intent_id uuid not null references public.circle_payment_intents(id) on delete restrict,
  recipient_user_wallet text not null,
  amount text not null,
  amount_units text not null,
  transaction_id text,
  tx_hash text,
  status text not null default 'pending',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circle_payment_recipients_status_check check (
    status in ('pending', 'submitted', 'confirmed', 'failed')
  )
);

create index if not exists circle_payment_recipients_intent_idx
  on public.circle_payment_recipients (payment_intent_id);

-- ─── Payment requests ───────────────────────────────────────────────────────
create table if not exists public.circle_payment_request_groups (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  requester_user_wallet text not null,
  per_amount text not null,
  per_amount_units text not null,
  asset text not null default 'USDC',
  reason text,
  target_mode text not null,
  status text not null default 'open',
  expires_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circle_request_group_mode_check check (
    target_mode in ('one', 'multiple', 'everyone')
  ),
  constraint circle_request_group_status_check check (
    status in ('open', 'completed', 'cancelled', 'expired')
  )
);

create table if not exists public.circle_payment_requests (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  group_id uuid references public.circle_payment_request_groups(id) on delete restrict,
  requester_user_wallet text not null,
  target_user_wallet text not null,
  amount text not null,
  amount_units text not null,
  asset text not null default 'USDC',
  reason text,
  status text not null default 'pending',
  expires_at timestamptz,
  payment_intent_id uuid references public.circle_payment_intents(id) on delete set null,
  transaction_id text,
  tx_hash text,
  idempotency_key text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circle_payment_requests_status_check check (
    status in ('pending', 'paid', 'declined', 'cancelled', 'expired')
  )
);

create index if not exists circle_payment_requests_circle_status_idx
  on public.circle_payment_requests (circle_id, status);

create index if not exists circle_payment_requests_target_idx
  on public.circle_payment_requests (target_user_wallet, status, created_at desc);

create unique index if not exists circle_payment_requests_idem_uidx
  on public.circle_payment_requests (requester_user_wallet, idempotency_key)
  where idempotency_key is not null;

-- ─── Circle Save ────────────────────────────────────────────────────────────
create table if not exists public.circle_save_accounts (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  status text not null default 'active',
  balance text not null default '0',
  balance_units text not null default '0',
  goal_name text,
  target_amount text,
  target_amount_units text,
  target_date date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circle_save_accounts_status_check check (
    status in ('active', 'frozen', 'closed')
  ),
  constraint circle_save_accounts_circle_uidx unique (circle_id)
);

create table if not exists public.circle_save_contributions (
  id uuid primary key default gen_random_uuid(),
  circle_save_account_id uuid not null references public.circle_save_accounts(id) on delete restrict,
  circle_id uuid not null references public.circles(id) on delete restrict,
  user_wallet text not null,
  amount text not null,
  amount_units text not null,
  asset text not null default 'USDC',
  transaction_id text,
  tx_hash text,
  status text not null default 'proposed',
  idempotency_key text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circle_save_contributions_status_check check (
    status in ('proposed', 'submitted', 'confirmed', 'failed', 'cancelled')
  )
);

create unique index if not exists circle_save_contributions_idem_uidx
  on public.circle_save_contributions (user_wallet, idempotency_key);

create index if not exists circle_save_contributions_account_idx
  on public.circle_save_contributions (circle_save_account_id, created_at desc);

create unique index if not exists circle_save_contributions_tx_hash_uidx
  on public.circle_save_contributions (lower(tx_hash))
  where tx_hash is not null;

create index if not exists circle_save_contributions_submitted_idx
  on public.circle_save_contributions (circle_id, status)
  where status = 'submitted';

-- ─── Circle Save pockets (fixed / flexible, like Swift+Save) ────────────────
create table if not exists public.circle_save_pockets (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  circle_save_account_id uuid not null references public.circle_save_accounts(id) on delete restrict,
  created_by_wallet text not null,
  name text not null,
  icon text not null default 'piggy',
  description text,
  target_amount text,
  target_amount_units text,
  current_balance text not null default '0',
  current_balance_units text not null default '0',
  currency text not null default 'USDC',
  status text not null default 'active',
  stop_at_target boolean not null default false,
  lock_kind text not null default 'flexible',
  lock_until timestamptz,
  lock_duration_days integer,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  archived_at timestamptz,
  constraint circle_save_pockets_name_len check (char_length(name) between 1 and 50),
  constraint circle_save_pockets_description_len check (
    description is null or char_length(description) <= 280
  ),
  constraint circle_save_pockets_status_check check (status in ('active', 'archived')),
  constraint circle_save_pockets_lock_kind_check check (lock_kind in ('flexible', 'fixed')),
  constraint circle_save_pockets_currency_check check (currency in ('USDC', 'EURC'))
);

create index if not exists circle_save_pockets_circle_idx
  on public.circle_save_pockets (circle_id, status, created_at desc);

alter table public.circle_save_contributions
  add column if not exists pocket_id uuid references public.circle_save_pockets(id) on delete restrict;

create index if not exists circle_save_contributions_pocket_idx
  on public.circle_save_contributions (pocket_id, created_at desc)
  where pocket_id is not null;

-- ─── Circle Earn (legacy tables kept; SwiftCircle no longer exposes Earn) ───
create table if not exists public.circle_earn_accounts (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  provider text not null default 'ledger',
  external_account_id text,
  principal text not null default '0',
  principal_units text not null default '0',
  current_value text not null default '0',
  current_value_units text not null default '0',
  status text not null default 'active',
  yield_info jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circle_earn_accounts_status_check check (
    status in ('active', 'frozen', 'closed')
  ),
  constraint circle_earn_accounts_circle_uidx unique (circle_id)
);

create table if not exists public.circle_earn_contributions (
  id uuid primary key default gen_random_uuid(),
  circle_earn_account_id uuid not null references public.circle_earn_accounts(id) on delete restrict,
  circle_id uuid not null references public.circles(id) on delete restrict,
  user_wallet text not null,
  amount text not null,
  amount_units text not null,
  asset text not null default 'USDC',
  transaction_id text,
  tx_hash text,
  status text not null default 'proposed',
  idempotency_key text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circle_earn_contributions_status_check check (
    status in ('proposed', 'submitted', 'confirmed', 'failed', 'cancelled')
  )
);

create unique index if not exists circle_earn_contributions_idem_uidx
  on public.circle_earn_contributions (user_wallet, idempotency_key);

create unique index if not exists circle_earn_contributions_tx_hash_uidx
  on public.circle_earn_contributions (lower(tx_hash))
  where tx_hash is not null;

create index if not exists circle_earn_contributions_submitted_idx
  on public.circle_earn_contributions (circle_id, status)
  where status = 'submitted';

-- ─── Withdrawal policies (never hard-code thresholds in app/frontend) ───────
create table if not exists public.circle_withdrawal_policies (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  product_type text not null,
  minimum_amount_units text not null default '0',
  maximum_amount_units text,
  required_approvals integer not null default 1,
  eligible_roles text[] not null default array['host', 'admin']::text[],
  initiator_counts_as_approval boolean not null default false,
  version integer not null default 1,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circle_withdrawal_policies_product_check check (
    product_type in ('save', 'earn')
  ),
  constraint circle_withdrawal_policies_approvals_check check (
    required_approvals >= 0 and required_approvals <= 20
  )
);

create index if not exists circle_withdrawal_policies_circle_idx
  on public.circle_withdrawal_policies (circle_id, product_type, active);

-- ─── Withdrawal proposals + approvals ───────────────────────────────────────
create table if not exists public.circle_withdrawal_proposals (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  product_type text not null,
  initiator_user_wallet text not null,
  amount text not null,
  amount_units text not null,
  asset text not null default 'USDC',
  destination_user_wallet text,
  destination_address text not null,
  reason text,
  policy_id uuid references public.circle_withdrawal_policies(id) on delete restrict,
  policy_version integer not null,
  required_approvals integer not null,
  approval_epoch integer not null default 1,
  status text not null default 'draft',
  risk_decision text not null default 'ALLOW',
  idempotency_key text not null,
  transaction_id text,
  tx_hash text,
  failure_reason text,
  expires_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint circle_withdrawal_proposals_product_check check (
    product_type in ('save', 'earn')
  ),
  constraint circle_withdrawal_proposals_status_check check (
    status in (
      'draft',
      'pending_policy',
      'pending_approval',
      'approved',
      'executing',
      'submitted',
      'confirmed',
      'rejected',
      'cancelled',
      'expired',
      'failed'
    )
  )
);

create unique index if not exists circle_withdrawal_proposals_idem_uidx
  on public.circle_withdrawal_proposals (circle_id, idempotency_key);

create index if not exists circle_withdrawal_proposals_circle_status_idx
  on public.circle_withdrawal_proposals (circle_id, status);

alter table public.circle_withdrawal_proposals
  add column if not exists pocket_id uuid references public.circle_save_pockets(id) on delete restrict;

create table if not exists public.circle_withdrawal_approvals (
  id uuid primary key default gen_random_uuid(),
  withdrawal_proposal_id uuid not null references public.circle_withdrawal_proposals(id) on delete restrict,
  circle_id uuid not null references public.circles(id) on delete restrict,
  approver_user_wallet text not null,
  decision text not null,
  approval_epoch integer not null default 1,
  created_at timestamptz not null default now(),
  constraint circle_withdrawal_approvals_decision_check check (
    decision in ('approved', 'rejected')
  ),
  constraint circle_withdrawal_approvals_unique unique (
    withdrawal_proposal_id, approver_user_wallet, approval_epoch
  )
);

create index if not exists circle_withdrawal_approvals_proposal_idx
  on public.circle_withdrawal_approvals (withdrawal_proposal_id);

-- ─── Ledger (canonical accounting; balances are derived) ────────────────────
create table if not exists public.circle_ledger_entries (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  actor_user_wallet text,
  entry_type text not null,
  product_type text not null,
  source text not null,
  destination text not null,
  amount_units text not null,
  asset text not null default 'USDC',
  purpose text not null,
  related_entity_type text,
  related_entity_id uuid,
  transaction_id text,
  tx_hash text,
  status text not null,
  idempotency_key text not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint circle_ledger_entry_type_check check (
    entry_type in (
      'contribution',
      'payment',
      'withdrawal',
      'refund',
      'failed_transaction',
      'reversal',
      'yield_adjustment'
    )
  ),
  constraint circle_ledger_product_check check (
    product_type in ('personal', 'save', 'earn', 'pay')
  ),
  constraint circle_ledger_status_check check (
    status in ('pending', 'submitted', 'confirmed', 'failed', 'reversed')
  )
);

create unique index if not exists circle_ledger_entries_idem_uidx
  on public.circle_ledger_entries (idempotency_key);

create index if not exists circle_ledger_entries_circle_idx
  on public.circle_ledger_entries (circle_id, created_at desc);

create index if not exists circle_ledger_entries_tx_idx
  on public.circle_ledger_entries (tx_hash)
  where tx_hash is not null;

-- ─── Activity (presentation; never source of financial truth) ────────────────
create table if not exists public.circle_activity (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid not null references public.circles(id) on delete restrict,
  actor_user_wallet text,
  activity_type text not null,
  entity_type text,
  entity_id uuid,
  summary text not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists circle_activity_circle_idx
  on public.circle_activity (circle_id, created_at desc);

-- ─── Audit (append-only) ────────────────────────────────────────────────────
create table if not exists public.circle_audit_logs (
  id uuid primary key default gen_random_uuid(),
  circle_id uuid references public.circles(id) on delete restrict,
  actor_user_wallet text,
  action text not null,
  entity_type text not null,
  entity_id text,
  metadata jsonb not null default '{}'::jsonb,
  request_id text,
  created_at timestamptz not null default now()
);

create index if not exists circle_audit_logs_circle_created_idx
  on public.circle_audit_logs (circle_id, created_at);

create index if not exists circle_audit_logs_action_idx
  on public.circle_audit_logs (action, created_at desc);

-- ─── Notification events (idempotent) ───────────────────────────────────────
create table if not exists public.circle_events (
  id uuid primary key default gen_random_uuid(),
  event_id text not null,
  circle_id uuid references public.circles(id) on delete restrict,
  event_type text not null,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint circle_events_event_id_uidx unique (event_id)
);

create table if not exists public.circle_notifications (
  id uuid primary key default gen_random_uuid(),
  event_id text not null,
  circle_id uuid references public.circles(id) on delete restrict,
  owner_wallet text not null,
  kind text not null,
  title text not null,
  body text not null,
  metadata jsonb not null default '{}'::jsonb,
  read_at timestamptz,
  created_at timestamptz not null default now(),
  constraint circle_notifications_event_owner_uidx unique (event_id, owner_wallet)
);

create index if not exists circle_notifications_owner_idx
  on public.circle_notifications (owner_wallet, created_at desc);

-- ─── Webhook receipts ───────────────────────────────────────────────────────
create table if not exists public.circle_webhook_receipts (
  id uuid primary key default gen_random_uuid(),
  provider_event_id text not null,
  tx_hash text,
  provider_transaction_id text,
  payload jsonb not null default '{}'::jsonb,
  processed_at timestamptz not null default now(),
  constraint circle_webhook_receipts_event_uidx unique (provider_event_id)
);

create index if not exists circle_webhook_receipts_tx_idx
  on public.circle_webhook_receipts (tx_hash)
  where tx_hash is not null;

-- ─── Configurable platform limits (backend-enforced) ────────────────────────
create table if not exists public.circle_platform_limits (
  id text primary key default 'default',
  max_members integer not null default 50,
  max_circles_per_user integer not null default 20,
  max_invitations_per_day integer not null default 50,
  max_payment_amount_units text not null default '100000000000',
  max_request_amount_units text not null default '100000000000',
  max_save_contribution_units text not null default '100000000000',
  max_earn_contribution_units text not null default '100000000000',
  max_withdrawal_amount_units text not null default '100000000000',
  max_pending_withdrawals integer not null default 5,
  invitation_ttl_hours integer not null default 168,
  updated_at timestamptz not null default now()
);

insert into public.circle_platform_limits (id)
values ('default')
on conflict (id) do nothing;

-- ─── Grants + RLS ───────────────────────────────────────────────────────────
alter table public.circles enable row level security;
alter table public.circle_members enable row level security;
alter table public.circle_invitations enable row level security;
alter table public.circle_messages enable row level security;
alter table public.circle_message_reads enable row level security;
alter table public.circle_message_reports enable row level security;
alter table public.circle_payment_intents enable row level security;
alter table public.circle_payment_recipients enable row level security;
alter table public.circle_payment_request_groups enable row level security;
alter table public.circle_payment_requests enable row level security;
alter table public.circle_save_accounts enable row level security;
alter table public.circle_save_contributions enable row level security;
alter table public.circle_save_pockets enable row level security;
alter table public.circle_earn_accounts enable row level security;
alter table public.circle_earn_contributions enable row level security;
alter table public.circle_withdrawal_policies enable row level security;
alter table public.circle_withdrawal_proposals enable row level security;
alter table public.circle_withdrawal_approvals enable row level security;
alter table public.circle_ledger_entries enable row level security;
alter table public.circle_activity enable row level security;
alter table public.circle_audit_logs enable row level security;
alter table public.circle_events enable row level security;
alter table public.circle_notifications enable row level security;
alter table public.circle_webhook_receipts enable row level security;
alter table public.circle_platform_limits enable row level security;

grant usage on schema public to service_role;

grant select, insert, update on public.circles to service_role;
grant select, insert, update on public.circle_members to service_role;
grant select, insert, update on public.circle_invitations to service_role;
grant select, insert, update on public.circle_messages to service_role;
grant select, insert, update on public.circle_message_reads to service_role;
grant select, insert, update on public.circle_message_reports to service_role;
grant select, insert, update on public.circle_payment_intents to service_role;
grant select, insert, update on public.circle_payment_recipients to service_role;
grant select, insert, update on public.circle_payment_request_groups to service_role;
grant select, insert, update on public.circle_payment_requests to service_role;
grant select, insert, update on public.circle_save_accounts to service_role;
grant select, insert, update on public.circle_save_contributions to service_role;
grant select, insert, update on public.circle_save_pockets to service_role;
grant select, insert, update on public.circle_earn_accounts to service_role;
grant select, insert, update on public.circle_earn_contributions to service_role;
grant select, insert, update on public.circle_withdrawal_policies to service_role;
grant select, insert, update on public.circle_withdrawal_proposals to service_role;
grant select, insert, update on public.circle_withdrawal_approvals to service_role;
grant select, insert, update on public.circle_ledger_entries to service_role;
