-- ═══ account-activity.sql ══════════════════════════════════════════════════

-- SwiftPay account activity ledger.
-- One row per confirmed transaction a feature performed from the browser
-- (Send, Request Payment, Swap, BatchPay, Circle, RecurePay, invoice payers).
-- Server-side features (Save, Earn, Payroll, Invoices received, ALLIE,
-- RecurePay autopay) are read from their own tables by /api/activity, so they
-- do not need to write here.

create extension if not exists pgcrypto;

create table if not exists public.account_activity (
  id uuid primary key default gen_random_uuid(),
  wallet_address text not null,
  source text not null,
  direction text not null default 'out',
  title text,
  counterparty text,
  amount text,
  token text,
  tx_hash text,
  -- Mirrored rows are written for the other side of a payment (the requester
  -- of a paid request). They only ever label an on-chain transfer the
  -- dashboard already sees; they are never shown on their own.
  mirrored boolean not null default false,
  metadata jsonb not null default '{}'::jsonb,
  occurred_at timestamptz not null default now(),
  created_at timestamptz not null default now(),

  constraint account_activity_source_check check (
    source in (
      'send', 'request', 'payroll', 'circle', 'swap', 'invoice',
      'save', 'earn', 'batch', 'recurepay', 'agent'
    )
  ),
  constraint account_activity_direction_check check (
    direction in ('in', 'out', 'internal')
  )
);

-- One row per (wallet, feature, transaction). Deliberately NOT a partial
-- index: the app upserts with ON CONFLICT (wallet_address, source, tx_hash),
-- which Postgres can only match to a partial index if the query repeats its
-- WHERE clause, and the Supabase client cannot. NULL tx_hash values are still
-- distinct, so rows without a hash never collide.
drop index if exists public.account_activity_wallet_source_tx_unique;
create unique index account_activity_wallet_source_tx_unique
  on public.account_activity (wallet_address, source, tx_hash);

create index if not exists account_activity_wallet_occurred_idx
  on public.account_activity (wallet_address, occurred_at desc);

alter table public.account_activity enable row level security;

grant select, insert, update, delete on public.account_activity to service_role;

drop policy if exists account_activity_no_client_access on public.account_activity;
create policy account_activity_no_client_access
  on public.account_activity
  for all
  using (false)
  with check (false);

-- ═══ support-chat.sql ══════════════════════════════════════════════════════

-- SwiftPay Support: conversations handed from the help assistant to a person.
--
-- The assistant answers from a curated help library at no cost; when it
-- can't, the customer opens a request that lands in /admin/support.
-- Signed-in customers are identified by wallet; guests (e.g. invoice payers)
-- by an email plus a private access token only their browser holds.
--
-- Run in the Supabase SQL editor. Safe to run more than once.

create table if not exists public.support_tickets (
  id uuid primary key default gen_random_uuid(),
  -- Short, human-friendly reference: SP-7Q3K9.
  reference text not null unique,
  wallet_address text,
  email text,
  -- sha256 of the guest's access token; the token itself is never stored.
  access_token_hash text not null,
  subject text not null,
  category text not null default 'general',
  priority text not null default 'normal',
  status text not null default 'open',
  -- Where the customer was when they asked (e.g. /invoice/…), for context.
  page_path text,
  last_message_at timestamptz not null default now(),
  -- Set when support replies and the customer hasn't read it yet.
  unread_by_customer boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint support_tickets_identity check (wallet_address is not null or email is not null),
  constraint support_tickets_priority_check check (priority in ('normal', 'high', 'urgent')),
  constraint support_tickets_status_check check (status in ('open', 'waiting_on_customer', 'resolved'))
);

create table if not exists public.support_messages (
  id uuid primary key default gen_random_uuid(),
  ticket_id uuid not null references public.support_tickets(id) on delete cascade,
  sender text not null,
  body text not null,
  created_at timestamptz not null default now(),
  constraint support_messages_sender_check check (sender in ('customer', 'agent', 'assistant', 'system')),
  constraint support_messages_body_len check (char_length(body) between 1 and 4000)
);

create index if not exists support_tickets_wallet_idx
  on public.support_tickets (wallet_address, last_message_at desc);
create index if not exists support_tickets_queue_idx
  on public.support_tickets (status, priority, last_message_at desc);
create index if not exists support_messages_ticket_idx
  on public.support_messages (ticket_id, created_at);

-- Server-only tables: the service role reads and writes them.
alter table public.support_tickets enable row level security;
alter table public.support_messages enable row level security;

grant all privileges on table public.support_tickets to postgres, service_role;
grant all privileges on table public.support_messages to postgres, service_role;

-- ═══ rate-limits.sql ═══════════════════════════════════════════════════════

-- Shared rate limits.
-- In-memory counters don't hold on serverless: every instance counts on its
-- own. This keeps one atomic counter per key and fixed window in Postgres.
create table if not exists public.rate_limit_windows (
  key text not null,
  window_start timestamptz not null,
  hits integer not null default 0,
  primary key (key, window_start)
);

alter table public.rate_limit_windows enable row level security;
revoke all on public.rate_limit_windows from anon, authenticated;
grant select, insert, update, delete on public.rate_limit_windows to service_role;

drop policy if exists rate_limit_windows_no_client_access on public.rate_limit_windows;
create policy rate_limit_windows_no_client_access
  on public.rate_limit_windows
  for all
  using (false)
  with check (false);

-- Counts one hit and returns true while the key is within its limit.
create or replace function public.consume_rate_limit(
  p_key text,
  p_max integer,
  p_window_seconds integer
) returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_window timestamptz :=
    to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  v_hits integer;
begin
  insert into public.rate_limit_windows as w (key, window_start, hits)
  values (p_key, v_window, 1)
  on conflict (key, window_start) do update set hits = w.hits + 1
  returning w.hits into v_hits;

  -- Occasional cleanup of finished windows keeps the table small.
  if random() < 0.01 then
    delete from public.rate_limit_windows where window_start < now() - interval '1 day';
  end if;

  return v_hits <= p_max;
end;
$$;

revoke all on function public.consume_rate_limit(text, integer, integer) from public, anon, authenticated;
grant execute on function public.consume_rate_limit(text, integer, integer) to service_role;

-- ═══ incoming-transfer-cursors.sql ═════════════════════════════════════════

-- Incoming payment scan cursors.
-- The "payment received" notifications read Transfer events from the Arc RPC
-- (the explorer API is behind a Cloudflare challenge on mainnet). The RPC caps
-- each query at a few thousand blocks, so each wallet remembers the last block
-- it was scanned to and the next scan only reads blocks after it.
create table if not exists public.incoming_transfer_cursors (
  chain_id integer not null,
  wallet_address text not null,
  last_block bigint not null,
  updated_at timestamptz not null default now(),
  primary key (chain_id, wallet_address)
);

alter table public.incoming_transfer_cursors enable row level security;
revoke all on public.incoming_transfer_cursors from anon, authenticated;
grant select, insert, update, delete on public.incoming_transfer_cursors to service_role;

drop policy if exists incoming_transfer_cursors_no_client_access on public.incoming_transfer_cursors;
create policy incoming_transfer_cursors_no_client_access
  on public.incoming_transfer_cursors
  for all
  using (false)
  with check (false);

-- ═══ app-lock.sql ══════════════════════════════════════════════════════════

-- App lock: a PIN, and optionally Face ID / fingerprint (WebAuthn passkeys),
-- that a signed-in user must enter when they come back to SwiftPay.
-- Keyed by the wallet the account signed in with. Server-only: the PIN hash
-- and passkey public keys are never readable from the browser.
create table if not exists public.app_locks (
  owner_wallet text primary key,
  -- scrypt$<N>$<r>$<p>$<salt b64url>$<hash b64url>
  pin_hash text not null,
  -- Minutes away from the app before it locks again.
  timeout_minutes integer not null default 1 check (timeout_minutes in (1, 5, 15)),
  failed_attempts integer not null default 0,
  locked_until timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.app_lock_passkeys (
  credential_id text primary key,
  owner_wallet text not null,
  public_key text not null,
  counter bigint not null default 0,
  transports text[],
  created_at timestamptz not null default now(),
  last_used_at timestamptz
);

create index if not exists app_lock_passkeys_owner_idx
  on public.app_lock_passkeys (owner_wallet);

alter table public.app_locks enable row level security;
alter table public.app_lock_passkeys enable row level security;
revoke all on public.app_locks from anon, authenticated;
revoke all on public.app_lock_passkeys from anon, authenticated;
grant select, insert, update, delete on public.app_locks to service_role;
grant select, insert, update, delete on public.app_lock_passkeys to service_role;

drop policy if exists app_locks_no_client_access on public.app_locks;
create policy app_locks_no_client_access
  on public.app_locks
  for all
  using (false)
  with check (false);

drop policy if exists app_lock_passkeys_no_client_access on public.app_lock_passkeys;
create policy app_lock_passkeys_no_client_access
  on public.app_lock_passkeys
  for all
  using (false)
  with check (false);

-- ═══ two-factor.sql ════════════════════════════════════════════════════════

-- Two-factor authentication: an authenticator-app code (TOTP) asked for on
-- every new sign-in, with single-use backup codes. Keyed by the wallet the
-- account signed in with. Server-only.
create table if not exists public.two_factor (
  owner_wallet text primary key,
  -- AES-256-GCM, key SWIFTPAY_MFA_KEY: v1.<iv>.<ciphertext+tag> (base64url)
  secret_encrypted text not null,
  -- The last time step accepted, so a code can't be used twice.
  last_step bigint not null default 0,
  -- sha256 hashes of the unused backup codes.
  backup_code_hashes text[] not null default '{}',
  failed_attempts integer not null default 0,
  locked_until timestamptz,
  enabled_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.two_factor enable row level security;
revoke all on public.two_factor from anon, authenticated;
grant select, insert, update, delete on public.two_factor to service_role;

drop policy if exists two_factor_no_client_access on public.two_factor;
create policy two_factor_no_client_access
  on public.two_factor
  for all
  using (false)
  with check (false);

