-- ═══ business-checkout.sql ═════════════════════════════════════════════════

-- SwiftPay Checkout: quick in-person charges for Business accounts.
-- A merchant charge (or a storefront charge the customer types in) is paid to
-- the business wallet by any route; the chain is the source of truth and each
-- transaction can be claimed by exactly one charge. Additive and idempotent.

create table if not exists public.business_charges (
  id uuid primary key default gen_random_uuid(),
  public_id text not null,
  wallet_address text not null references public.profiles(wallet_address) on delete restrict,
  kind text not null default 'MERCHANT',
  status text not null default 'OPEN',
  currency text not null default 'USDC',
  amount text not null,
  tip_amount text not null default '0',
  amount_received text not null default '0',
  overpayment text not null default '0',
  note text,
  payer_wallet text,
  pending_method text,
  pending_ref text,
  pending_started_at timestamptz,
  reported_amount text,
  created_block bigint,
  idempotency_key text,
  expires_at timestamptz not null,
  paid_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint business_charges_public_id_unique unique (public_id),
  constraint business_charges_kind_check check (
    kind in ('MERCHANT', 'STOREFRONT')
  ),
  constraint business_charges_status_check check (
    status in ('OPEN', 'PAID', 'EXPIRED', 'CANCELLED')
  ),
  constraint business_charges_currency_check check (
    currency in ('USDC', 'EURC')
  ),
  constraint business_charges_pending_method_check check (
    pending_method is null
    or pending_method in ('WALLET', 'SWIFTPAY', 'ONRAMP', 'BRIDGE')
  ),
  constraint business_charges_note_len check (
    note is null or char_length(note) <= 140
  )
);

create index if not exists business_charges_wallet_idx
  on public.business_charges (wallet_address, created_at desc);

-- A retried "Charge" tap with the same key returns the first charge.
create unique index if not exists business_charges_idempotency_unique
  on public.business_charges (wallet_address, idempotency_key)
  where idempotency_key is not null;

create index if not exists business_charges_open_expiry_idx
  on public.business_charges (expires_at)
  where status = 'OPEN';

create index if not exists business_charges_matchable_idx
  on public.business_charges (wallet_address, created_block)
  where status = 'OPEN' and pending_method in ('ONRAMP', 'BRIDGE');

create table if not exists public.business_charge_payments (
  id uuid primary key default gen_random_uuid(),
  charge_id uuid not null references public.business_charges(id) on delete restrict,
  tx_hash text not null,
  amount text not null,
  asset text not null,
  source text not null,
  matched_by text not null,
  payer_wallet text,
  block_number bigint,
  status text not null default 'CONFIRMED',
  paid_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  constraint business_charge_payments_tx_unique unique (tx_hash),
  constraint business_charge_payments_asset_check check (
    asset in ('USDC', 'EURC')
  ),
  constraint business_charge_payments_source_check check (
    source in ('SWIFTPAY', 'WALLET', 'ONRAMP', 'BRIDGE', 'RECONCILE')
  ),
  constraint business_charge_payments_matched_by_check check (
    matched_by in ('RECEIPT', 'SCAN')
  )
);

create index if not exists business_charge_payments_charge_idx
  on public.business_charge_payments (charge_id);

-- Where the hash-less matcher (card/bank, bridge) last read each merchant's
-- incoming transfers. Same shape as incoming_transfer_cursors.
create table if not exists public.business_checkout_scan_cursors (
  chain_id integer not null,
  wallet_address text not null,
  last_block bigint not null,
  updated_at timestamptz not null default now(),
  primary key (chain_id, wallet_address)
);

alter table public.business_charges enable row level security;
alter table public.business_charge_payments enable row level security;
alter table public.business_checkout_scan_cursors enable row level security;

revoke all on public.business_charges from anon, authenticated;
revoke all on public.business_charge_payments from anon, authenticated;
revoke all on public.business_checkout_scan_cursors from anon, authenticated;

grant select, insert, update, delete on public.business_charges to service_role;
grant select, insert, update, delete on public.business_charge_payments to service_role;
grant select, insert, update, delete on public.business_checkout_scan_cursors to service_role;

drop policy if exists business_charges_no_client_access on public.business_charges;
create policy business_charges_no_client_access
  on public.business_charges
  for all
  using (false)
  with check (false);

drop policy if exists business_charge_payments_no_client_access on public.business_charge_payments;
create policy business_charge_payments_no_client_access
  on public.business_charge_payments
  for all
  using (false)
  with check (false);

drop policy if exists business_checkout_scan_cursors_no_client_access on public.business_checkout_scan_cursors;
create policy business_checkout_scan_cursors_no_client_access
  on public.business_checkout_scan_cursors
  for all
  using (false)
  with check (false);

-- Activity rows from charge payers carry source 'checkout'. 'points' is
-- already written by the app but was missing from the constraint. A superset
-- of the previous list, so existing rows stay valid.
alter table public.account_activity
  drop constraint if exists account_activity_source_check;

alter table public.account_activity
  add constraint account_activity_source_check check (
    source in (
      'send', 'request', 'payroll', 'circle', 'swap', 'invoice',
      'save', 'earn', 'batch', 'recurepay', 'agent', 'points', 'checkout'
    )
  );

-- ═══ wallet-transfer-history.sql ═══════════════════════════════════════════

-- Wallet transfer history read from the Arc RPC.
-- The explorer API answers server requests with a Cloudflare challenge on
-- mainnet, so Activity's on-chain history (a wallet's own transfers and its
-- ALLIE Agent Wallet's) is read from Transfer events instead and kept here.
-- Each wallet's cursor remembers the newest block read and how far back the
-- history has been filled; every load reads forward from the newest block and
-- fills a little more of the past.
create table if not exists public.wallet_transfer_history (
  chain_id integer not null,
  wallet_address text not null,
  tx_hash text not null,
  log_index integer not null,
  direction text not null,
  counterparty text not null,
  symbol text not null,
  amount text not null,
  block_number bigint not null,
  occurred_at timestamptz,
  created_at timestamptz not null default now(),
  primary key (chain_id, wallet_address, tx_hash, log_index, direction),
  constraint wallet_transfer_history_direction_check check (direction in ('in', 'out'))
);

create index if not exists wallet_transfer_history_recent_idx
  on public.wallet_transfer_history (chain_id, wallet_address, block_number desc);

create table if not exists public.wallet_history_cursors (
  chain_id integer not null,
  wallet_address text not null,
  -- Newest block read so far.
  newest_block bigint not null,
  -- Oldest block read so far; filling stops at floor_block.
  oldest_block bigint not null,
  floor_block bigint not null,
  updated_at timestamptz not null default now(),
  primary key (chain_id, wallet_address)
);

alter table public.wallet_transfer_history enable row level security;
alter table public.wallet_history_cursors enable row level security;
revoke all on public.wallet_transfer_history from anon, authenticated;
revoke all on public.wallet_history_cursors from anon, authenticated;
grant select, insert, update, delete on public.wallet_transfer_history to service_role;
grant select, insert, update, delete on public.wallet_history_cursors to service_role;

drop policy if exists wallet_transfer_history_no_client_access on public.wallet_transfer_history;
create policy wallet_transfer_history_no_client_access
  on public.wallet_transfer_history
  for all
  using (false)
  with check (false);

drop policy if exists wallet_history_cursors_no_client_access on public.wallet_history_cursors;
create policy wallet_history_cursors_no_client_access
  on public.wallet_history_cursors
  for all
  using (false)
  with check (false);

-- ═══ kyc.sql ═══════════════════════════════════════════════════════════════

-- Personal KYC for the Naira ramp (Prembly). A wallet passes Tier 1 (phone
-- OTP + BVN/NIN) once, then optionally Tier 2 (liveness + face match) for
-- higher daily limits. Additive and idempotent. Never stores the raw BVN,
-- NIN, selfie, or Prembly photo.

create table if not exists public.kyc_profiles (
  wallet_address text primary key references public.profiles(wallet_address) on delete restrict,
  country text not null default 'NG',
  tier smallint not null default 0,
  status text not null default 'NONE',
  provider text not null default 'PREMBLY',
  id_type text,
  id_hash text,
  id_last4 text,
  first_name text,
  last_name text,
  middle_name text,
  dob text,
  phone_e164 text,
  phone_verified_at timestamptz,
  otp_provider text,
  tier1_verified_at timestamptz,
  tier2_verified_at timestamptz,
  liveness_score numeric,
  face_match_score numeric,
  flags jsonb not null default '{}'::jsonb,
  provider_ref text,
  reviewed_by text,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint kyc_profiles_tier_check check (tier in (0, 1, 2)),
  constraint kyc_profiles_status_check check (
    status in ('NONE', 'PENDING', 'VERIFIED', 'MANUAL_REVIEW', 'REJECTED')
  ),
  constraint kyc_profiles_id_type_check check (id_type is null or id_type in ('BVN', 'NIN'))
);

create unique index if not exists kyc_profiles_id_hash_verified_unique
  on public.kyc_profiles (id_hash)
  where status = 'VERIFIED' and id_hash is not null;

create table if not exists public.kyc_attempts (
  id uuid primary key default gen_random_uuid(),
  wallet_address text not null references public.profiles(wallet_address) on delete cascade,
  subject text not null default 'PERSON',
  step text not null,
  id_hash text,
  result text not null,
  reason_code text,
  provider_code text,
  provider_ref text,
  created_at timestamptz not null default now(),
  constraint kyc_attempts_subject_check check (subject in ('PERSON', 'BUSINESS')),
  constraint kyc_attempts_step_check check (
    step in (
      'PHONE_OTP', 'ID_LOOKUP', 'LIVENESS', 'FACE_MATCH',
      'CAC_LOOKUP', 'TIN_LOOKUP', 'DIRECTOR_MATCH'
    )
  ),
  constraint kyc_attempts_result_check check (result in ('PASS', 'FAIL', 'ERROR'))
);

create index if not exists kyc_attempts_wallet_idx
  on public.kyc_attempts (wallet_address, created_at desc);

create index if not exists kyc_attempts_hash_idx
  on public.kyc_attempts (id_hash, created_at desc)
  where id_hash is not null;

alter table public.kyc_profiles enable row level security;
alter table public.kyc_attempts enable row level security;

revoke all on public.kyc_profiles from anon, authenticated;
revoke all on public.kyc_attempts from anon, authenticated;

grant select, insert, update, delete on public.kyc_profiles to service_role;
grant select, insert, update, delete on public.kyc_attempts to service_role;

drop policy if exists kyc_profiles_no_client_access on public.kyc_profiles;
create policy kyc_profiles_no_client_access
  on public.kyc_profiles
  for all
  using (false)
  with check (false);

drop policy if exists kyc_attempts_no_client_access on public.kyc_attempts;
create policy kyc_attempts_no_client_access
  on public.kyc_attempts
  for all
  using (false)
  with check (false);

-- ═══ kyb.sql ═══════════════════════════════════════════════════════════════

-- Business KYB for the Naira ramp (Prembly CAC + TIN). Sits on top of
-- personal KYC: the person acting still needs Tier 1. Additive and
-- idempotent. One company number verifies one wallet.

create table if not exists public.kyb_profiles (
  wallet_address text primary key references public.profiles(wallet_address) on delete restrict,
  country text not null default 'NG',
  level text not null default 'NONE',
  status text not null default 'NONE',
  company_type text,
  rc_number text,
  company_name text,
  registration_date text,
  cac_status text,
  tin_hash text,
  tin_last4 text,
  tin_name text,
  director_match jsonb,
  flags jsonb not null default '{}'::jsonb,
  provider_ref_cac text,
  provider_ref_tin text,
  reviewed_by text,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint kyb_profiles_level_check check (level in ('NONE', 'BASIC', 'FULL')),
  constraint kyb_profiles_status_check check (
    status in ('NONE', 'PENDING', 'VERIFIED', 'MANUAL_REVIEW', 'REJECTED')
  ),
  constraint kyb_profiles_company_type_check check (
    company_type is null or company_type in ('RC', 'BN', 'IT')
  )
);

create unique index if not exists kyb_profiles_company_verified_unique
  on public.kyb_profiles (company_type, rc_number)
  where status = 'VERIFIED' and rc_number is not null and company_type is not null;

alter table public.kyb_profiles enable row level security;

revoke all on public.kyb_profiles from anon, authenticated;
grant select, insert, update, delete on public.kyb_profiles to service_role;

drop policy if exists kyb_profiles_no_client_access on public.kyb_profiles;
create policy kyb_profiles_no_client_access
  on public.kyb_profiles
  for all
  using (false)
  with check (false);

-- Which name an off-ramp beneficiary matched: the owner's KYC name or the
-- company's CAC name. Null on rows saved before KYB. Additive.
alter table public.ramp_beneficiaries
  add column if not exists name_match text;

alter table public.ramp_beneficiaries
  drop constraint if exists ramp_beneficiaries_name_match_check;
alter table public.ramp_beneficiaries
  add constraint ramp_beneficiaries_name_match_check check (
    name_match is null or name_match in ('OWNER', 'COMPANY')
  );

-- Papers a business sends for manual review (CAC status report, board
-- resolution). Only paths and metadata live here; the files sit in the
-- private kyb-documents bucket, read by reviewers through short signed URLs.
alter table public.kyb_profiles
  add column if not exists documents jsonb not null default '[]'::jsonb;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('kyb-documents', 'kyb-documents', false, 3145728, array['application/pdf', 'image/jpeg', 'image/png'])
on conflict (id) do nothing;
